// Rotate answer order deterministically so the daily deck does not teach a
// fixed answer-position pattern. The original correct choice stays intact.
const answerShifts = [0, 1, 2, 3, 1, 3, 2, 0, 3, 1, 2, 3, 0, 1, 2];
export const DAILY_ITEMS = dailyItems.map((item, index) => {
  const shift = answerShifts[index % answerShifts.length];
  const correctIndex = 'ABCD'.indexOf(item.correctOption);
  const options = [...item.options.slice(shift), ...item.options.slice(0, shift)];
  return { ...item, options, correctOption: 'ABCD'[(correctIndex - shift + 4) % 4] };
});
